% mathsmap-diagram-colours {"version":1,"kind":"geometry","base":[],"semantic":[{"name":"measuredRegionFill","hex":"D4E8FF","reason":"identifies the triangle outside the circular opening"}],"reference":"source page 18, p18-q2-g-diagram"}
\begin{tikzpicture}[x=8mm,y=8mm,line width=0.8pt,every node/.style={font=\fontsize{10}{12}\selectfont,text=black}]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{measuredRegionFill}{HTML}{D4E8FF}
\coordinate (A) at (0,0);
\coordinate (B) at (4.2,0);
\coordinate (C) at (2.8,-2);
\pgfmathsetmacro{\sideA}{sqrt(1.4*1.4+2*2)}
\pgfmathsetmacro{\sideB}{sqrt(2.8*2.8+2*2)}
\pgfmathsetmacro{\perimeter}{4.2+\sideA+\sideB}
\pgfmathsetmacro{\rr}{8.4/\perimeter}
\pgfmathsetmacro{\cx}{(4.2*\sideB+4.2*2.8)/\perimeter}
\fill[measuredRegionFill] (A)--(B)--(C)--cycle;
\fill[white] (\cx,-\rr) circle[radius=\rr];
\draw (A)--(B)--(C)--cycle;
\draw (\cx,-\rr) circle[radius=\rr];
\draw[dashed,line width=0.4pt] (\cx,-\rr)--(\cx,0);
\fill[black] (\cx,-\rr) circle[radius=0.5mm];
\draw[<->,line width=0.4pt] (0,0.35)--(4.2,0.35) node[midway,above=0.5mm] {$14\ \mathrm{mm}$};
\draw[line width=0.4pt] (0,0.2)--(0,0.5) (4.2,0.2)--(4.2,0.5);
\draw[<->,line width=0.4pt] (4.55,-2)--(4.55,0) node[midway,right=1mm] {$8\ \mathrm{mm}$};
\draw[line width=0.4pt] (4.4,-2)--(4.7,-2) (4.4,0)--(4.7,0);
\node[anchor=north east] at (1.55,-1.25) {$3.2\ \mathrm{mm}$};
\draw[->,line width=0.4pt] (1.45,-1.2) .. controls (1.6,-0.55) and (2.15,-0.25) .. (\cx,{-\rr/2});
\end{tikzpicture}

